// Check emergency stop
if (($env.AUTOPILOT_STOP || '').toLowerCase() === 'true') {
  return [{ json: { stopped: true } }];
}
return [{ json: { stopped: false } }];

const today = new Date().toISOString().split('T')[0];
const systemPrompt = 'You are Eki social media strategist. Brand: Eki - AI automation platform for businesses. Tone: professional, innovative, approachable. You generate unique content for each platform. Return ONLY valid JSON.';
const userPrompt = `Generate social media content for ${today}. Return JSON with this exact structure:
{
  "tiktok": { "hook": "attention-grabbing first line", "video_script": "30-60 sec script with scenes", "caption": "short caption", "hashtags": "#tag1 #tag2 (5-8 tags)" },
  "instagram": { "hook": "reel hook", "video_script": "reel script", "caption": "engaging caption with CTA", "hashtags": "#tag1 #tag2 (10-15 tags)" },
  "facebook": { "hook": "scroll-stopping opener", "caption": "longer post with value and CTA", "hashtags": "#tag1 #tag2 (3-5 tags)", "video_script": "" }
}
Rules: No offensive content. No false claims. No medical/legal/financial promises. No spammy hashtags. Each platform MUST have unique caption. Focus on AI automation value.`;

return [{
  json: {
    requestBody: {
      model: 'llama-3.3-70b-versatile',
      temperature: 0.85,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
}];

// Parse Groq/OpenAI response into 3 platform items
const item = $input.first().json;
let rawContent = '';

if (item.choices && item.choices[0]) {
  rawContent = item.choices[0].message.content;
} else {
  return [{ json: { error: 'No AI response', raw: JSON.stringify(item) } }];
}

// Extract JSON (handle markdown code blocks if any)
let jsonStr = rawContent;
const jsonMatch = rawContent.match(/```(?:json)?\s*([\s\S]*?)```/);
if (jsonMatch) jsonStr = jsonMatch[1].trim();

let content;
try {
  content = JSON.parse(jsonStr);
} catch(e) {
  return [{ json: { error: 'JSON parse failed: ' + e.message, raw: rawContent } }];
}

const today = new Date().toISOString().split('T')[0];
const platforms = ['tiktok', 'instagram', 'facebook'];
const results = [];

for (const platform of platforms) {
  const p = content[platform] || {};
  results.push({
    json: {
      date: today,
      platform: platform,
      content_type: platform === 'tiktok' ? 'short_video' : platform === 'instagram' ? 'reel' : 'post',
      hook: p.hook || '',
      caption: p.caption || '',
      hashtags: p.hashtags || '',
      video_script: p.video_script || '',
      status: 'generated',
      autopilot_status: 'pending',
      scheduled_at: '',
      published_at: '',
      error: ''
    }
  });
}

return results;

// Safety checks
const items = $input.all();
const offensiveRe = /\b(fuck|shit|damn|bitch|nigger|faggot|retard)\b/i;
const falseClaimRe = /\b(guaranteed|100%|proven to|always works|never fails|instant results)\b/i;
const medLegalFinRe = /\b(cure|diagnose|legal advice|financial advice|investment returns|medical treatment|prescription)\b/i;
const spamHashRe = /\b(follow4follow|f4f|like4like|l4l|followback|instalike|likeforlike)\b/i;

const allCaptions = items.map(i => (i.json.caption || '').toLowerCase());
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const issues = [];
  const text = (item.caption || '') + ' ' + (item.video_script || '');

  if (offensiveRe.test(text)) issues.push('offensive');
  if (falseClaimRe.test(text)) issues.push('false_claim');
  if (medLegalFinRe.test(text)) issues.push('med_legal_fin');
  if (spamHashRe.test(item.hashtags || '')) issues.push('spam_hashtags');

  const dupes = allCaptions.filter(c => c === (item.caption || '').toLowerCase()).length;
  if (dupes > 1) issues.push('duplicate');

  const passed = issues.length === 0;
  results.push({
    json: {
      ...item,
      status: passed ? 'approved' : 'flagged',
      error: passed ? '' : issues.join(',')
    }
  });
}

return results;

// Check if autopilot posting is enabled and Buffer key exists
const autopilotOn = ($env.AUTOPILOT_SOCIAL_POSTING || '').toLowerCase() === 'true';
const hasBuffer = !!$env.BUFFER_API_KEY;
const items = $input.all();

const results = items.map(item => ({
  json: {
    ...item.json,
    should_post: autopilotOn && hasBuffer && item.json.status === 'approved',
    posting_method: hasBuffer ? 'buffer' : 'none'
  }
}));

return results;

// Check if Buffer post succeeded or failed
const item = $input.first().json;
const success = item.success === true || item.updates || (item.id && !item.error);

return [{
  json: {
    buffer_success: success,
    buffer_response: item,
    platform: $('Should Auto-Post?').first().json.platform,
    caption: $('Should Auto-Post?').first().json.caption,
    hashtags: $('Should Auto-Post?').first().json.hashtags,
    date: $('Should Auto-Post?').first().json.date
  }
}];

